    curves = [
        r"\begin{tabular}{lrrrr}",
        r"\toprule",
        r"Heads & Delim. limpa & Delim. reversa & Indent. limpa & Indent. reversa \\",
        r"\midrule",
    ]
    for n in (0, 4, 8, 16, 32, 64, 128, 384):
